'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/invoices — itemized invoices you can send to customers for payment.
 */
class Invoices {
  constructor(client) {
    this.client = client;
  }

  /**
   * List invoices.
   * @param {object} [params] Query params (e.g. page, limit, status)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/invoices', params));
  }

  /**
   * Create an invoice.
   * @param {object} params
   * @param {object} params.customer         { first_name, last_name, email, phone, ... }
   * @param {string} params.currency         e.g. "XOF"
   * @param {Array}  params.items            [{ name, quantity, unit_price }, ...]
   * @param {number} [params.tax_rate]       0–100
   * @param {number} [params.discount_amount]
   * @param {string} [params.notes]
   * @param {string} [params.terms]
   * @param {string} [params.issued_at]      ISO date
   * @param {string} [params.due_at]         ISO date
   * @param {boolean} [params.send_reminders]
   */
  create(params) {
    return this.client.request('POST', '/v1/invoices', params);
  }

  /**
   * Retrieve an invoice by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/invoices/${encodeURIComponent(id)}`);
  }

  /**
   * Update (partially) an invoice.
   * @param {string} id
   * @param {object} params
   */
  update(id, params) {
    return this.client.request('PATCH', `/v1/invoices/${encodeURIComponent(id)}`, params);
  }

  /**
   * Delete/cancel an invoice.
   * @param {string} id
   */
  delete(id) {
    return this.client.request('DELETE', `/v1/invoices/${encodeURIComponent(id)}`);
  }

  /**
   * Send (or resend) the invoice to the customer by email.
   * @param {string} id
   */
  send(id) {
    return this.client.request('POST', `/v1/invoices/${encodeURIComponent(id)}/send`);
  }

  /**
   * Retrieve the structured data needed to render a PDF of the invoice.
   * @param {string} id
   */
  pdfData(id) {
    return this.client.request('GET', `/v1/invoices/${encodeURIComponent(id)}/pdf-data`);
  }
}

module.exports = Invoices;
